#!/usr/bin/env node
/**
 * 百度千帆 API - 生产级认证与请求示例
 * =====================================
 *
 * 此脚本演示了生产环境中如何：
 * 1. 获取和缓存访问令牌（带过期追踪）
 * 2. 实现自动令牌刷新（提前 5 天）
 * 3. 正确处理各种错误类别
 * 4. 实现指数退避重试
 * 5. 使用 Authorization header 传递令牌
 *
 * 运行前请设置环境变量：
 *     export BAIDU_API_KEY="your_api_key"
 *     export BAIDU_SECRET_KEY="your_secret_key"
 *
 * 运行：node auth_example.js
 */

const http = require('http');
const https = require('https');
const url = require('url');
const querystring = require('querystring');

// ============================================================================
// 常量配置
// ============================================================================

const Config = {
    // 端点配置
    BASE_URL: 'https://aip.baidubce.com',
    TOKEN_ENDPOINT: '/oauth/3.0/token',
    CHAT_ENDPOINT: '/rpc/2.0/ai_custom/v1/wenxinworkshop/chat/completions',

    // OAuth 配置
    GRANT_TYPE: 'client_credentials',

    // 请求配置（性能调优后的值）
    TIMEOUT_MS: 15000,  // 15 秒
    MAX_RETRIES: 3,

    // 重试配置（性能调优后的值）
    INITIAL_DELAY_MS: 200,
    MAX_DELAY_MS: 5000,
    BACKOFF_MULTIPLIER: 1.5,

    // 令牌配置
    REFRESH_BUFFER_MS: 5 * 24 * 60 * 60 * 1000,  // 提前 5 天刷新
};

// 错误代码到分类的映射
const ERROR_CATEGORIES = {
    110: 'TOKEN_INVALID',      // 令牌无效
    111: 'TOKEN_EXPIRED',      // 令牌过期
    17: 'RATE_LIMIT_DAILY',   // 每日配额超限
    18: 'RATE_LIMIT_QPS',     // QPS 超限
    282000: 'SERVER_ERROR',   // 服务器内部错误
    336001: 'INVALID_PARAM',  // 参数无效
    336003: 'REQUEST_TOO_LARGE',  // 请求体过大
};

// ============================================================================
// 日志工具
// ============================================================================

function log(level, message) {
    const timestamp = new Date().toISOString();
    console.log(`${timestamp} - ${level} - ${message}`);
}

function info(message) { log('INFO', message); }
function warn(message) { log('WARN', message); }
function error(message) { log('ERROR', message); }
function debug(message) { if (process.env.DEBUG) log('DEBUG', message); }

// ============================================================================
// HTTP 工具函数
// ============================================================================

function makeHttpRequest(options, requestBody = null) {
    return new Promise((resolve, reject) => {
        const protocol = options.protocol || 'https:';
        const lib = protocol === 'https:' ? https : http;

        const req = lib.request(options, (res) => {
            let body = '';
            res.on('data', chunk => body += chunk);
            res.on('end', () => {
                try {
                    const json = JSON.parse(body);
                    resolve({
                        status: res.statusCode,
                        headers: res.headers,
                        body: json,
                        raw: body
                    });
                } catch (e) {
                    resolve({
                        status: res.statusCode,
                        headers: res.headers,
                        body: { raw: body },
                        raw: body
                    });
                }
            });
        });

        req.on('error', reject);
        req.on('timeout', () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        if (requestBody) {
            req.write(requestBody);
        }
        req.end();

        // 设置超时
        req.setTimeout(options.timeout || Config.TIMEOUT_MS);
    });
}

// ============================================================================
// TokenCache 类
// ============================================================================

class TokenCache {
    constructor() {
        this.accessToken = null;
        this.expiresAt = 0;  // Unix 时间戳（毫秒）
        this.fetchedAt = 0;
    }

    isValid() {
        if (!this.accessToken) return false;
        // 如果在刷新缓冲期内或已过期，视为无效
        return Date.now() < (this.expiresAt - Config.REFRESH_BUFFER_MS);
    }

    timeUntilExpiry() {
        return Math.max(0, this.expiresAt - Date.now());
    }
}

// ============================================================================
// APIResponse 类
// ============================================================================

class APIResponse {
    constructor(statusCode, body, success = true) {
        this.statusCode = statusCode;
        this.body = body;
        this.success = success;
        this.requestId = body.request_id || null;

        // 提取错误信息
        if (!success) {
            this.errorCode = body.error_code || body.error;
            this.errorMessage = body.error_msg || body.message || '';
        }
    }
}

// ============================================================================
// BaiduQianfanClient 类
// ============================================================================

class BaiduQianfanClient {
    constructor(apiKey, secretKey) {
        this.apiKey = apiKey;
        this.secretKey = secretKey;
        this.tokenCache = new TokenCache();
        info('Baidu Qianfan 客户端初始化完成');
    }

    // ------------------------------------------------------------------------
    // 令牌管理
    // ------------------------------------------------------------------------

    async getToken() {
        /**
         * 获取访问令牌，使用缓存并自动刷新。
         * @returns {string} 有效的访问令牌
         */
        if (this.tokenCache.isValid()) {
            debug(`使用缓存的令牌（剩余 ${(this.tokenCache.timeUntilExpiry() / 1000 / 60 / 60).toFixed(1)} 小时）`);
            return this.tokenCache.accessToken;
        }

        info('令牌已过期或即将过期，正在刷新...');
        await this.refreshToken();

        if (!this.tokenCache.accessToken) {
            throw new Error('无法从百度千帆 API 获取访问令牌');
        }

        return this.tokenCache.accessToken;
    }

    async refreshToken() {
        /**
         * 强制刷新访问令牌。
         */
        try {
            const params = {
                grant_type: Config.GRANT_TYPE,
                client_id: this.apiKey,
                client_secret: this.secretKey,
            };

            const urlStr = `${Config.BASE_URL}${Config.TOKEN_ENDPOINT}?${querystring.stringify(params)}`;
            const options = {
                method: 'GET',
                timeout: 10000,
                headers: {
                    'User-Agent': 'Mozilla/5.0 (compatible; BaiduQianfanClient/1.0)',
                }
            };

            const parsedUrl = url.parse(urlStr);
            Object.assign(options, parsedUrl);

            const response = await makeHttpRequest(options);

            if (response.status === 200) {
                if (response.body.error) {
                    error(`令牌刷新失败：${JSON.stringify(response.body)}`);
                    this.tokenCache.accessToken = null;
                    return;
                }

                // 更新缓存
                this.tokenCache.accessToken = response.body.access_token;
                const expiresIn = response.body.expires_in || 2592000;
                this.tokenCache.expiresAt = Date.now() + (expiresIn * 1000);
                this.tokenCache.fetchedAt = Date.now();

                info(`令牌刷新成功，有效期：${expiresIn} 秒（${Math.floor(expiresIn / 86400)} 天）`);
            } else {
                error(`令牌刷新失败，HTTP ${response.status}`);
                this.tokenCache.accessToken = null;
            }

        } catch (e) {
            error(`令牌刷新请求失败：${e.message}`);
            this.tokenCache.accessToken = null;
        }
    }

    // ------------------------------------------------------------------------
    // 重试逻辑
    // ------------------------------------------------------------------------

    calculateBackoff(attempt) {
        /**
         * 计算带抖动的指数退避延迟（毫秒）。
         * @param {number} attempt 重试尝试次数
         * @returns {number} 延迟毫秒数
         */
        if (attempt === 0) return 0;

        // 指数退避
        let delayMs = Config.INITIAL_DELAY_MS * Math.pow(Config.BACKOFF_MULTIPLIER, attempt);
        delayMs = Math.min(delayMs, Config.MAX_DELAY_MS);

        // 添加最多 25% 的随机抖动
        const jitter = Math.random() * delayMs * 0.25;
        return Math.floor(delayMs + jitter);
    }

    sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    // ------------------------------------------------------------------------
    // 错误处理
    // ------------------------------------------------------------------------

    getErrorCategory(errorCode) {
        return ERROR_CATEGORIES[errorCode] || 'UNKNOWN';
    }

    shouldRetry(response) {
        /**
         * 判断是否应该重试请求。
         */
        const category = this.getErrorCategory(response.errorCode);

        // 不重试的情况
        if (['INVALID_PARAM', 'REQUEST_TOO_LARGE', 'RATE_LIMIT_DAILY'].includes(category)) {
            return false;
        }

        // 需要重试的情况
        return ['SERVER_ERROR', 'RATE_LIMIT_QPS'].includes(category);
    }

    // ------------------------------------------------------------------------
    // 核心请求方法
    // ------------------------------------------------------------------------

    async makeRequestWithRetry(method, path, body = null, params = {}) {
        /**
         * 执行 HTTP 请求，带自动重试和令牌刷新逻辑。
         */
        const maxRetries = Config.MAX_RETRIES;
        let attempt = 0;
        let lastResponse = null;

        while (attempt <= maxRetries) {
            // 获取令牌
            let accessToken;
            try {
                accessToken = await this.getToken();
            } catch (e) {
                return new APIResponse(500, {}, false);
            }

            // 构建 URL（添加 access_token 参数）
            let urlStr = `${Config.BASE_URL}${path}`;

            // 合并参数
            const allParams = { ...params };
            allParams.access_token = accessToken;  // 使用 query param 方式

            if (Object.keys(allParams).length > 0) {
                urlStr += '?' + querystring.stringify(allParams);
            }

            const options = {
                method: method,
                timeout: Config.TIMEOUT_MS,
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${accessToken}`,  // 推荐方式
                }
            };

            try {
                const response = await makeHttpRequest(options, body ? JSON.stringify(body) : null);

                // 检查是否为错误响应
                const errorCode = response.body.error_code || response.body.error;
                const success = response.status === 200 && !errorCode;

                const apiResponse = new APIResponse(response.status, response.body, success);

                debug(`请求响应：HTTP ${apiResponse.statusCode}, error_code=${apiResponse.errorCode}`);

                if (!success) {
                    const category = this.getErrorCategory(apiResponse.errorCode);

                    // 令牌错误：刷新并重试
                    if (category === 'TOKEN_INVALID' || category === 'TOKEN_EXPIRED') {
                        warn(`令牌错误（${apiResponse.errorCode}），正在刷新...`);
                        await this.refreshToken();
                        if (attempt < maxRetries) {
                            const delay = this.calculateBackoff(attempt + 1);
                            info(`等待 ${delay}ms 后重试...`);
                            await this.sleep(delay);
                            attempt++;
                            lastResponse = apiResponse;
                            continue;
                        }
                        return apiResponse;
                    }

                    // 其他错误
                    if (this.shouldRetry(apiResponse)) {
                        attempt++;
                        if (attempt <= maxRetries) {
                            const delay = this.calculateBackoff(attempt);
                            info(`错误 ${apiResponse.errorCode}，尝试 ${attempt}/${maxRetries}，等待 ${delay}ms 后重试...`);
                            await this.sleep(delay);
                            lastResponse = apiResponse;
                            continue;
                        }
                    }

                    return apiResponse;
                }

                info(`请求成功，request_id: ${apiResponse.requestId}`);
                return apiResponse;

            } catch (e) {
                if (e.message === 'Request timeout') {
                    warn(`请求超时，尝试 ${attempt + 1}/${maxRetries}`);
                } else {
                    warn(`网络错误：${e.message}，尝试 ${attempt + 1}/${maxRetries}`);
                }

                attempt++;
                if (attempt <= maxRetries) {
                    const delay = this.calculateBackoff(attempt);
                    await this.sleep(delay);
                } else {
                    return new APIResponse(
                        e.message === 'Request timeout' ? 504 : 503,
                        {},
                        false
                    );
                }
            }
        }

        return new APIResponse(
            lastResponse ? lastResponse.statusCode : 500,
            {},
            false
        );
    }

    // ------------------------------------------------------------------------
    // 公共 API
    // ------------------------------------------------------------------------

    async chatCompletion(messages, temperature = 0.8, model = 'ernie-bot') {
        /**
         * 发送对话完成请求。
         * @param {Array} messages - 对话历史
         * @param {number} temperature - 采样温度
         * @param {string} model - 模型名称
         * @returns {APIResponse}
         */
        const payload = {
            messages: messages,
            temperature: temperature,
            stream: false,
            model: model,
        };

        return await this.makeRequestWithRetry(
            'POST',
            Config.CHAT_ENDPOINT,
            payload
        );
    }
}

// ============================================================================
// 简单辅助函数
// ============================================================================

async function getAccessTokenSimple(apiKey, secretKey) {
    /**
     * 简单方式获取访问令牌。
     */
    try {
        const params = {
            grant_type: Config.GRANT_TYPE,
            client_id: apiKey,
            client_secret: secretKey,
        };

        const urlStr = `${Config.BASE_URL}${Config.TOKEN_ENDPOINT}?${querystring.stringify(params)}`;
        const options = {
            method: 'GET',
            timeout: 10000,
        };

        const parsedUrl = url.parse(urlStr);
        Object.assign(options, parsedUrl);

        const response = await makeHttpRequest(options);

        if (response.status === 200 && response.body.access_token) {
            return response.body.access_token;
        }
        return null;

    } catch (e) {
        error(`获取令牌失败：${e.message}`);
        return null;
    }
}

async function chatCompletionSimple(accessToken, messages) {
    /**
     * 简单方式发送对话请求。
     */
    try {
        const urlStr = `${Config.BASE_URL}${Config.CHAT_ENDPOINT}?access_token=${accessToken}`;
        const payload = JSON.stringify({ messages: messages });

        const options = {
            method: 'POST',
            timeout: Config.TIMEOUT_MS,
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payload),
            }
        };

        const parsedUrl = url.parse(urlStr);
        Object.assign(options, parsedUrl);

        const response = await makeHttpRequest(options, payload);
        return response.body;

    } catch (e) {
        return { error: e.message };
    }
}

// ============================================================================
// 主函数 - 演示
// ============================================================================

async function main() {
    const apiKey = process.env.BAIDU_API_KEY || 'YOUR_API_KEY';
    const secretKey = process.env.BAIDU_SECRET_KEY || 'YOUR_SECRET_KEY';

    if (apiKey === 'YOUR_API_KEY' || secretKey === 'YOUR_SECRET_KEY') {
        console.log('\n=== 配置说明 ===');
        console.log('请设置环境变量或使用以下示例：');
        console.log('  export BAIDU_API_KEY="your_api_key"');
        console.log('  export BAIDU_SECRET_KEY="your_secret_key"');
        console.log('\n或者修改代码中的 apiKey 和 secretKey 值。\n');
        console.log('以下为演示输出（使用示例令牌流程）：\n');
    }

    // ========================================================================
    // 演示 1: 简单方式
    // ========================================================================
    console.log('=' .repeat(60));
    console.log('演示 1: 简单方式 - 获取令牌');
    console.log('='.repeat(60));

    if (apiKey !== 'YOUR_API_KEY') {
        const token = await getAccessTokenSimple(apiKey, secretKey);
        if (token) {
            console.log(`✓ 令牌获取成功（前 20 个字符）: ${token.substring(0, 20)}...`);
        } else {
            console.log('✗ 令牌获取失败');
        }
    } else {
        console.log('[模拟] 令牌获取流程：');
        console.log('  GET /oauth/3.0/token');
        console.log('    ?grant_type=client_credentials');
        console.log('    &client_id=<API_KEY>');
        console.log('    &client_secret=<SECRET_KEY>');
        console.log('  Response: {access_token: \'xxx\', expires_in: 2592000}');
    }

    // ========================================================================
    // 演示 2: 生产级客户端
    // ========================================================================
    console.log('\n' + '='.repeat(60));
    console.log('演示 2: 生产级客户端');
    console.log('='.repeat(60));

    try {
        const client = new BaiduQianfanClient(apiKey, secretKey);
        console.log('✓ 客户端初始化完成');

        // 获取令牌
        console.log('\n-> 获取令牌...');
        const token = await client.getToken();
        if (apiKey === 'YOUR_API_KEY') {
            console.log('[模拟] 令牌：24.xxx.xxx.2592000.xxx-12345678');
        } else {
            console.log(`✓ 令牌：${token.substring(0, 20)}...`);
        }

        // 发送对话请求
        console.log('\n-> 发送对话请求...');
        const messages = [{ role: 'user', content: '你好，请简单介绍一下你自己。' }];

        if (apiKey === 'YOUR_API_KEY') {
            console.log('[模拟] 请求：');
            console.log('  POST /rpc/2.0/ai_custom/v1/wenxinworkshop/chat/completions');
            console.log('  Headers: Authorization: Bearer <token>');
            console.log('  Body: {messages: [...]}');
            console.log('[模拟] 响应：{result: \'我是 ERNIE-Bot...\', usage: {...}}');
        } else {
            const response = await client.chatCompletion(messages);
            if (response.success) {
                console.log('✓ 请求成功');
                console.log(`  request_id: ${response.requestId}`);
                const result = response.body.result || '';
                console.log(`  result: ${result.substring(0, 100)}...`);
                if (response.body.usage) {
                    const usage = response.body.usage;
                    console.log(`  tokens: prompt=${usage.prompt_tokens}, completion=${usage.completion_tokens}`);
                }
            } else {
                console.log(`✗ 请求失败：${response.errorCode} - ${response.errorMessage}`);
            }
        }

    } catch (e) {
        error(`客户端执行出错：${e.message}`);
    }

    // ========================================================================
    // 演示 3: 配置摘要
    // ========================================================================
    console.log('\n' + '='.repeat(60));
    console.log('当前配置摘要');
    console.log('='.repeat(60));
    console.log(`Base URL:        ${Config.BASE_URL}`);
    console.log(`Token Endpoint:  ${Config.TOKEN_ENDPOINT}`);
    console.log(`Chat Endpoint:   ${Config.CHAT_ENDPOINT}`);
    console.log(`Timeout:         ${Config.TIMEOUT_MS}ms (${Config.TIMEOUT_MS / 1000}秒)`);
    console.log(`Max Retries:     ${Config.MAX_RETRIES}`);
    console.log(`Initial Delay:   ${Config.INITIAL_DELAY_MS}ms`);
    console.log(`Backoff Mult:    ${Config.BACKOFF_MULTIPLIER}`);
    console.log(`Max Delay:       ${Config.MAX_DELAY_MS}ms`);
    console.log(`Refresh Buffer:  ${(Config.REFRESH_BUFFER_MS / 1000 / 3600).toFixed(0)} 小时 (5 天)`);

    console.log('\n' + '='.repeat(60));
    console.log('演示完成！');
    console.log('='.repeat(60));
}

// 运行
main().catch(err => {
    error(`程序执行出错：${err.message}`);
    process.exit(1);
});
